# Karen v2 script: all prerecorded lines. {emo} inside text = face switch at that point of the audio
# (time = char position / length * duration). Builds app/commands.json (keeps name, grammar is rebuilt).
import json,re
C=[]
def cmd(id,emotion,phrases,lines,follow=None):
    C.append(dict(id=id,emotion=emotion,phrases=phrases,lines=lines,**({'follow':follow} if follow else {})))
