for k,v in SYS_MORE.items(): SYS[k]=(SYS[k][0],SYS[k][1]+v)
YES=['да.','ага','угу','конечн','точно','верно','правильн','давай']; NO=['нет','неа','мимо']
def L(id,i,t,extra=None):
    d={'file':f'audio/{id}-{i}.ogg','text':t};d.update(extra or {});return d
def mk(prefix,lines):
    out=[]
    for i,x in enumerate(lines):
        if isinstance(x,str): out.append(L(prefix,i,x));continue
        fl={k:dict(emotion=b['emotion'],lines=mk(f"{prefix}{i}{k}",b['lines'])) for k,b in x['follow'].items()}
        out.append(L(prefix,i,x['text'],{'follow':fl}))
    return out
for c in C:
    c['lines']=mk(c['id'],c['lines'])
    if c.get('follow'): c['follow']={k:dict(emotion=b['emotion'],lines=mk(f"{c['id']}{k}",b['lines'])) for k,b in c['follow'].items()}
d=json.load(open('app/commands.json'))
d['commands']=C;d['system']={k:{'emotion':e,'lines':[L(k,i,t) for i,t in enumerate(ls)]} for k,(e,ls) in SYS.items()}
d['yes']=YES;d['no']=NO
d['grammar']=list(dict.fromkeys(d['grammar']+GRAM))
d['_doc']=("Интенты: фраза срабатывает, если каждое слово-основа — начало слова реплики (точка в конце = слово целиком). Первый совпавший побеждает. "
 "text: {emotion} внутри — смена лица в этот момент аудио. follow: {yes,no,any,none} — Карен ждёт ответ (да/нет, любая фраза, тишина); ветки могут иметь свой follow.")
json.dump(d,open('app/commands.json','w'),ensure_ascii=False,indent=1)
def walk(ls):
    for l in ls:
        yield l
        for b in (l.get('follow') or {}).values(): yield from walk(b['lines'])
allL=[l for c in C for l in walk(c['lines'])]+[l for c in C for b in (c.get('follow') or {}).values() for l in walk(b['lines'])]+[l for s in d['system'].values() for l in s['lines']]
clean=lambda t:re.sub(r'\{\w+\}\s*','',t)
print('lines',len(allL),'chars',sum(len(clean(l['text'])) for l in allL))
